        const SliverToBoxAdapter(child: SizedBox(height:24)),
        SliverToBoxAdapter(child: Padding(padding: const EdgeInsets.symmetric(horizontal:16), child: Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [const Text('Tous les produits', style: TextStyle(fontWeight: FontWeight.w900, fontSize:16)), GestureDetector(onTap: (){}, child: const Text('Voir tout', style: TextStyle(color: MarketColors.red, fontSize:12, fontWeight: FontWeight.w800)))]))),
